CREATE TABLE public.practice_questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category text NOT NULL CHECK (category IN ('CCNA','CCNP','Interview')),
  question_text text NOT NULL,
  options jsonb NOT NULL CHECK (jsonb_typeof(options) = 'array' AND jsonb_array_length(options) = 4),
  correct_option text NOT NULL,
  explanation text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT correct_in_options CHECK (options ? correct_option)
);
CREATE INDEX practice_questions_category_idx ON public.practice_questions(category);
GRANT SELECT ON public.practice_questions TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.practice_questions TO authenticated;
GRANT ALL ON public.practice_questions TO service_role;
ALTER TABLE public.practice_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "practice questions public read" ON public.practice_questions FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "practice questions admin insert" ON public.practice_questions FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "practice questions admin update" ON public.practice_questions FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "practice questions admin delete" ON public.practice_questions FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin'));

CREATE OR REPLACE FUNCTION public.get_random_practice_questions(_category text, _limit int DEFAULT 10)
RETURNS SETOF public.practice_questions
LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path = public
AS $$
  SELECT * FROM public.practice_questions WHERE category = _category ORDER BY random() LIMIT LEAST(GREATEST(_limit,1),50);
$$;
GRANT EXECUTE ON FUNCTION public.get_random_practice_questions(text,int) TO anon, authenticated;

